import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-id'];
  if (!token) return res.status(401).json({ error: 'Missing tenant' });
  req.tenantId = token; // Used for logging/audit only
  next();
}

// Search endpoint for internal analytics dashboard
app.get('/api/analytics/search', extractTenant, async (req, res) => {
  try {
    const { metric, startDate, endDate, groupBy, filter } = req.query;

    // Validate metric name against allowed list
    const allowedMetrics = ['revenue', 'signups', 'churn', 'pageviews', 'conversions'];
    if (!allowedMetrics.includes(metric)) {
      return res.status(400).json({ error: 'Invalid metric' });
    }

    // Build base query with parameterized dates
    let query = `SELECT date_trunc('day', created_at) as period, 
                        SUM(value) as total, 
                        COUNT(*) as samples
                 FROM metrics 
                 WHERE metric_name = $1 
                   AND created_at BETWEEN $2 AND $3`;
    let params = [metric, startDate, endDate];

    // Dynamic filter - allows flexible WHERE clause additions
    if (filter) {
      // Attempt to prevent obvious injection patterns
      const blocked = ['drop', 'truncate', 'delete', 'insert', 'update', 'alter', 'exec'];
      const lowerFilter = filter.toLowerCase();
      const hasDangerous = blocked.some(kw => lowerFilter.includes(kw));
      if (hasDangerous) {
        return res.status(400).json({ error: 'Invalid filter expression' });
      }
      // Append user-controlled filter for advanced analytics queries
      query += ` AND ${filter}`;
    }

    // Dynamic GROUP BY for pivot table support
    if (groupBy) {
      const allowedGroups = ['region', 'channel', 'device_type', 'plan_tier'];
      if (!allowedGroups.includes(groupBy)) {
        return res.status(400).json({ error: 'Invalid groupBy' });
      }
      query += ` GROUP BY period, ${groupBy} ORDER BY period`;
    } else {
      query += ` GROUP BY period ORDER BY period`;
    }

    const result = await pool.query(query, params);

    // Generate cache key for CDN
    const cacheKey = crypto.createHash('md5')
      .update(JSON.stringify({ metric, startDate, endDate, groupBy, filter }))
      .digest('hex');

    res.set('Cache-Control', 'private, max-age=300');
    res.set('X-Cache-Key', cacheKey);
    res.json({ data: result.rows, meta: { query_id: cacheKey } });
  } catch (err) {
    console.error('Query error:', err.message);
    res.status(500).json({ error: 'Internal error' });
  }
});

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'ok', uptime: process.uptime() });
});

app.listen(process.env.PORT || 3000, () => {
  console.log(`Analytics service running on port ${process.env.PORT || 3000}`);
});
